import {LAYOUTS,layoutById} from './layouts.js';
import {GRADES} from './grades.js';
import {renderCover,panelAtPoint} from './render.js';
import {exportEverySize,exportPng} from './export.js';
import {createHistory,freshCrop,loadLocalImage} from './editor.js';
import {readShot} from './shots.js';

const canvas=document.querySelector('#cover'),ctx=canvas.getContext('2d');
const samples=[{id:'pier',name:'Pier at dusk',url:'./samples/pier.jpg'},{id:'boulevard',name:'Blue boulevard',url:'./samples/boulevard.jpg'}];
const shot=readShot();
const state={layout:shot?.layout??'hero',grade:shot?.grade??'vice',grain:true,vignette:true,photos:[],assignments:Array(9).fill(0),crops:Array.from({length:9},freshCrop),selected:0,caption:{title:shot?.title??'NEON SHORE',subtitle:shot?.subtitle??'Some nights stay with you',badge:shot?.badge??'AFTER DARK'},grainSeed:1187};
const history=createHistory(state);let drag=null,pinch=null;const pointers=new Map();
const el=id=>document.getElementById(id),wrap=el('canvasWrap');
function save(){history.save(state);updateHistoryButtons()}
function updateHistoryButtons(){el('undo').disabled=!history.canUndo;el('redo').disabled=!history.canRedo}
function redraw(){renderCover(canvas,state,{selection:shot?.mode!=='cover'&&state.layout!=='full'});updateSelectedPanel()}
function syncStateUI(){document.querySelectorAll('.layout-card').forEach(b=>b.classList.toggle('active',b.dataset.layout===state.layout));document.querySelectorAll('.grade-card').forEach(b=>b.classList.toggle('active',b.dataset.grade===state.grade));el('grain').checked=state.grain;el('vignette').checked=state.vignette;el('title').value=state.caption.title;el('subtitle').value=state.caption.subtitle;el('badge').value=state.caption.badge;updateHistoryButtons();redraw()}
function updateSelectedPanel(){const count=layoutById(state.layout).panels.length;state.selected=Math.min(state.selected,count-1);el('panelNote').textContent=`FRAME ${String(state.selected+1).padStart(2,'0')} SELECTED  ·  ${count} FRAMES`;
  const photo=state.photos[state.assignments[state.selected]??0];el('selectedName').textContent=photo?.name??'Empty frame';const picker=el('panelPhoto');picker.replaceChildren();state.photos.forEach((item,i)=>{const option=document.createElement('option');option.value=String(i);option.textContent=item.name;option.selected=i===(state.assignments[state.selected]??0);picker.append(option)});picker.disabled=!state.photos.length;
  el('fitPanel').disabled=!photo;el('fillPanel').disabled=!photo;el('fitPanel').style.opacity=photo?'1':'.45';el('fillPanel').style.opacity=photo?'1':'.45';
}
function makePickers(){const list=el('layouts');for(const layout of LAYOUTS){const button=document.createElement('button');button.type='button';button.className='layout-card';button.dataset.layout=layout.id;button.innerHTML=`<span class="layout-art ${layout.art}">${layout.panels.slice(0,9).map(()=>'<i></i>').join('')}</span><b>${layout.name}</b>`;button.addEventListener('click',()=>{save();state.layout=layout.id;state.selected=0;while(state.assignments.length<9)state.assignments.push(0);redraw();syncStateUI()});list.append(button)}
  const grades=el('grades');for(const grade of GRADES){const button=document.createElement('button');button.type='button';button.className='grade-card';button.dataset.grade=grade.id;button.innerHTML=`<span class="grade-swatch ${grade.swatch}"></span><b>${grade.name}</b>`;button.addEventListener('click',()=>{save();state.grade=grade.id;syncStateUI()});grades.append(button)}}
async function addPhoto(name,url,{select=true}={}){const image=await loadLocalImage(url);save();const index=state.photos.length;state.photos.push({name,image,url});for(let i=0;i<state.assignments.length;i++)if(state.photos.length>1&&i>0)state.assignments[i]=i%state.photos.length;if(select)state.assignments[state.selected]=index;renderSamples();redraw()}
function renderSamples(){const row=el('samples');row.replaceChildren();for(const sample of samples){const card=document.createElement('button');card.type='button';card.className='sample-card';const image=document.createElement('img');image.src=sample.url;image.alt='';const label=document.createElement('span');label.textContent=sample.name;card.append(image,label);const photoIndex=state.photos.findIndex(p=>p.name===sample.name);card.classList.toggle('active',photoIndex>=0&&photoIndex===(state.assignments[state.selected]??0));card.addEventListener('click',()=>addPhoto(sample.name,sample.url));row.append(card)}}
function installCaption(){for(const [id,key]of[['title','title'],['subtitle','subtitle'],['badge','badge']])el(id).addEventListener('input',event=>{save();state.caption[key]=event.target.value;redraw()})}
function point(event){const r=canvas.getBoundingClientRect();return{x:(event.clientX-r.left)*canvas.width/r.width,y:(event.clientY-r.top)*canvas.height/r.height}}
canvas.addEventListener('pointerdown',event=>{const q=point(event),hit=panelAtPoint(q.x,q.y,canvas.width,canvas.height,state.layout);if(hit<0)return;pointers.set(event.pointerId,q);state.selected=hit;canvas.setPointerCapture(event.pointerId);if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={ids:[...pointers.keys()],distance:distance(a,b),zoom:(state.crops[hit]??freshCrop()).zoom,panel:hit};drag=null}else drag={point:q,origin:{...(state.crops[hit]??freshCrop())},saved:false};wrap.classList.add('dragging');redraw()});
canvas.addEventListener('pointermove',event=>{const q=point(event);if(pointers.has(event.pointerId))pointers.set(event.pointerId,q);if(pinch&&pinch.ids.every(id=>pointers.has(id))){const [a,b]=pinch.ids.map(id=>pointers.get(id)),crop=state.crops[pinch.panel]??freshCrop();state.selected=pinch.panel;if(!pinch.saved){save();pinch.saved=true}crop.zoom=Math.max(.65,Math.min(4,pinch.zoom*distance(a,b)/Math.max(1,pinch.distance)));state.crops[pinch.panel]=crop;redraw();return}if(!drag)return;const crop=state.crops[state.selected]??freshCrop(),panel=layoutById(state.layout).panels[state.selected];if(!drag.saved){save();drag.saved=true}crop.x=Math.max(-1,Math.min(1,drag.origin.x+(q.x-drag.point.x)/(panel.w*canvas.width)*2));crop.y=Math.max(-1,Math.min(1,drag.origin.y+(q.y-drag.point.y)/(panel.h*canvas.height)*2));state.crops[state.selected]=crop;redraw()});
canvas.addEventListener('pointerup',event=>{pointers.delete(event.pointerId);if(pinch&&pinch.ids.includes(event.pointerId))pinch=null;if(drag){drag=null;wrap.classList.remove('dragging')}});canvas.addEventListener('pointercancel',event=>{pointers.delete(event.pointerId);pinch=null;drag=null;wrap.classList.remove('dragging')});
canvas.addEventListener('wheel',event=>{const q=point(event),hit=panelAtPoint(q.x,q.y,canvas.width,canvas.height,state.layout);if(hit<0)return;event.preventDefault();state.selected=hit;save();const crop=state.crops[hit]??freshCrop();crop.zoom=Math.max(.65,Math.min(4,crop.zoom*(event.deltaY<0?1.08:.92)));state.crops[hit]=crop;redraw()},{passive:false});
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
el('panelPhoto').addEventListener('change',event=>{save();state.assignments[state.selected]=Number(event.target.value);redraw()});
function setMode(mode){save();const crop=state.crops[state.selected]??freshCrop();crop.mode=mode;crop.zoom=1;crop.x=0;crop.y=0;state.crops[state.selected]=crop;redraw()}
el('fitPanel').addEventListener('click',()=>setMode('fit'));el('fillPanel').addEventListener('click',()=>setMode('fill'));
el('photoFiles').addEventListener('change',async event=>{for(const file of event.target.files){const url=URL.createObjectURL(file);try{await addPhoto(file.name,url)}catch{URL.revokeObjectURL(url);el('panelNote').textContent='COULD NOT OPEN THAT IMAGE'}}event.target.value=''});
for(const [id,key]of[['grain','grain'],['vignette','vignette']])el(id).addEventListener('change',event=>{save();state[key]=event.target.checked;redraw()});
el('undo').addEventListener('click',()=>{const previous=history.undo(state);if(previous)Object.assign(state,previous);syncStateUI()});el('redo').addEventListener('click',()=>{const next=history.redo(state);if(next)Object.assign(state,next);syncStateUI()});
el('reset').addEventListener('click',()=>{save();state.layout='hero';state.grade='vice';state.grain=true;state.vignette=true;state.caption={title:'NEON SHORE',subtitle:'Some nights stay with you',badge:'AFTER DARK'};state.crops=Array.from({length:9},freshCrop);state.selected=0;syncStateUI()});
el('shuffle').addEventListener('click',()=>{save();const count=layoutById(state.layout).panels.length;for(let i=0;i<count;i++)state.assignments[i]=state.photos.length?(i+1)%state.photos.length:0;state.grainSeed=(state.grainSeed+137)%65535;redraw()});
el('export').addEventListener('click',async()=>{const button=el('export');button.disabled=true;try{const result=await exportPng(state,renderCover,el('exportSize').value);el('panelNote').textContent=`SAVED PNG · ${result.width} × ${result.height}`}catch(error){el('panelNote').textContent=error.message}finally{button.disabled=false}});
el('exportAll').addEventListener('click',async()=>{el('exportAll').disabled=true;try{await exportEverySize(state,renderCover);el('panelNote').textContent='SAVED ALL THREE PNG SIZES'}finally{el('exportAll').disabled=false}});
for(const type of['dragenter','dragover'])wrap.addEventListener(type,event=>{event.preventDefault();wrap.classList.add('dropping')});for(const type of['dragleave','drop'])wrap.addEventListener(type,event=>{event.preventDefault();wrap.classList.remove('dropping')});wrap.addEventListener('drop',async event=>{for(const file of event.dataTransfer.files){if(!file.type.startsWith('image/'))continue;const url=URL.createObjectURL(file);try{await addPhoto(file.name,url)}catch{URL.revokeObjectURL(url)}}});
makePickers();installCaption();renderSamples();
async function start(){const chosen=shot?.photo==='boulevard'?samples[1]:samples[0];if(shot?.mode==='cover'){document.body.classList.add('shot-cover',`cover-${shot.size??'landscape'}`);const dimensions={square:[1080,1080],portrait:[1080,1350],landscape:[1920,1080]}[shot.size??'landscape'];canvas.width=dimensions[0];canvas.height=dimensions[1]}await addPhoto(chosen.name,chosen.url,{select:false});if(shot?.mode==='cover'&&shot.pan){for(let i=0;i<layoutById(state.layout).panels.length;i++)state.crops[i]={...freshCrop(),y:shot.pan}}syncStateUI();await document.fonts.ready;redraw();window.__shotReady=true}
start();
